    function resetEditorFields(){const defaults={preset:'custom',mode:'local',numClips:'3',aspect:'9:16',format:'720',saveFolder:'',captionStyle:'bold',captionPosition:'bottom',captionFont:'Arial',captionSize:'0',captionColor:'#ffffff',focus:'balanced',music:'',watermark:'',intro:'',outro:'',language:'',whisperModel:'',whisperDevice:'',outputHeight:'1920',cropPosition:'.5',fitMode:'crop',zoom:'1',layout:'single',startTime:'0',endTime:'30'};Object.entries(defaults).forEach(([id,value])=>{if($(id))$(id).value=value;});['autoReframe','removeSilence','jumpCuts','normalizeAudio','denoiseAudio','fillerWords'].forEach(id=>{if($(id))$(id).checked=id==='autoReframe';});$('autoReframe').dispatchEvent(new Event('change'));updateLabels();syncFrameClass();}
