    function renderSetup(report){state.setup=report||{};const ff=report?.ffmpeg?.ready;const fp=report?.ffprobe?.ready;const gpu=report?.gpu?.cuda_available;const key=report?.keys?.selected_provider_configured;const rows=[['FFmpeg',ff?'Ready':'Missing',ff],['FFprobe',fp?'Ready':'Missing',fp],['CUDA',gpu?(report.gpu.device_name||'Ready'):'CPU fallback',gpu],['LLM ranking',key?`${report.keys.selected_provider} key configured`:(report?.keys?.offline_fallback?'Offline fallback enabled':'Key required'),Boolean(key||report?.keys?.offline_fallback)],['Storage',`${report?.storage?.free_disk_gb??'--'} GB free`,Boolean(report?.ready_for_local)]];$('setupList').innerHTML=rows.map(row=>`<div class="setup-row ${row[2]?'ok':'warn'}"><span>${esc(row[0])}</span><strong>${esc(row[1])}</strong></div>`).join('');$('setupSummary').textContent=report?.warnings?.length?report.warnings[0]:'Your local workspace is ready. You can change these choices later in Settings.';if(report?.first_run)$('setupModal').hidden=false;}
    async function loadSystem(){try{const r=await fetch('/api/system');const info=await r.json();const gpu=info.gpu||{};$('healthText').textContent=info.ffmpeg?'FFmpeg ready':'FFmpeg missing';$('healthDot').classList.toggle('warn',!info.ffmpeg);$('gpuText').textContent=gpu.cuda_available?'CUDA ready':'CPU fallback';$('statGpu').textContent=gpu.cuda_available?'CUDA':'CPU';$('systemDetails').textContent=`FFmpeg: ${info.ffmpeg?'ready':'missing'}\nWhisper: ${info.whisper_model} (${info.whisper_device})\nGPU: ${gpu.cuda_available?`${gpu.device_name||'CUDA ready'}`:`${gpu.reason||'unavailable'}`}\nFree disk: ${info.free_disk_gb} GB\nConcurrent jobs: ${info.max_concurrent_jobs}`;renderSetup(info.setup||{});}catch(e){$('healthText').textContent='Status unavailable';$('healthDot').classList.add('warn');}}
    async function loadJobs(query=''){
      const projectGrid=$('projectGrid');
      const libraryGrid=$('libraryGrid');
      if (!state.jobs.length) { StudioUI.showSkeletons(projectGrid, 3, 'card'); StudioUI.showSkeletons(libraryGrid, 3, 'card'); }
      try {
        const search=query?`&q=${encodeURIComponent(query)}`:'';
        const data=await StudioAPI.json(`/api/jobs?include_archived=${state.showArchived?'true':'false'}&limit=500${search}`);
        state.jobs=Array.isArray(data.jobs)?data.jobs.filter(job=>job&&typeof job==='object'):[];
        renderProjects(); renderQueue(); renderBatchMonitor(); renderLogFilters();
        $('statProjects').textContent=Number.isFinite(Number(data.total))?data.total:state.jobs.length;
        $('statDone').textContent=state.jobs.filter(j=>j.status==='done').length;
        $('statClips').textContent=state.jobs.reduce((n,j)=>n+(Array.isArray(j.result?.shorts)?j.result.shorts.length:0),0);
      } catch(e) {
        StudioUI.clearBusy(projectGrid); StudioUI.clearBusy(libraryGrid);
        toast(e.message,true);
      }
    }
    function projectCard(job){
      const req=job.request&&typeof job.request==='object'?job.request:{};
      const title=job.name||req.url||job.id;
      const count=Array.isArray(job.result?.shorts)?job.result.shorts.length:0;
      const status=job.status||'ready';
      const statusClass=status==='done'?'done':status==='error'||status==='cancelled'?'error':status==='running'||status==='queued'||status==='interrupted'?'run':'';
      const pct=StudioUI.progressPercent(job);
      const progress=['queued','running','interrupted'].includes(status)?`<div class="mini-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}" aria-label="${esc(title)} progress"><span style="width:${pct}%"></span></div>`:'';
      const retry=job.can_retry?`<button class="secondary" data-project-action="retry" data-project-id="${esc(job.id)}" type="button">${status==='draft'?'Run':'Retry'}</button>`:'';
      return `<article class="project-card" data-open-job="${esc(job.id)}" tabindex="0" role="button" aria-label="Open project ${esc(title)}"><div class="project-thumb">${status==='done'?'>':status==='running'?'...':status==='interrupted'?'!':'+'}</div><div class="project-info"><strong>${esc(title)}</strong><div class="project-meta"><span>${esc(fmtDate(job.created_at))}</span><span class="badge ${statusClass}">${esc(status)}${count?` - ${count} clips`:''}</span></div>${progress}<div class="project-card-actions">${retry}<button class="ghost" data-project-action="duplicate" data-project-id="${esc(job.id)}" type="button">Duplicate</button><button class="ghost" data-project-action="archive" data-project-id="${esc(job.id)}" type="button">${job.archived?'Unarchive':'Archive'}</button><button class="danger" data-project-action="delete" data-project-id="${esc(job.id)}" type="button">Delete</button></div></div></article>`;
    }
    function renderProjects(){
      const html=state.jobs.length?state.jobs.map(projectCard).join(''):'<div class="empty">No projects yet. Start with a video or a YouTube URL.</div>';
      $('projectGrid').innerHTML=html; $('libraryGrid').innerHTML=html;
      StudioUI.clearBusy($('projectGrid')); StudioUI.clearBusy($('libraryGrid'));
      document.querySelectorAll('[data-open-job]').forEach(el=>{el.addEventListener('click',e=>{if(e.target.closest('[data-project-action]'))return;openJob(el.dataset.openJob);});el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openJob(el.dataset.openJob);}});});
      document.querySelectorAll('[data-project-action]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();projectAction(el.dataset.projectAction,el.dataset.projectId,el);}));
    }
    async function projectAction(action,id,button){if(!id)return;if(action==='delete'&&!confirm('Delete this project record? Rendered media will be preserved and the project can be restored.'))return;if(action==='archive'&&!confirm('Change this project\'s archive status?'))return;if(button)button.disabled=true;const method=action==='delete'?'DELETE':'POST';const endpoint=`/api/jobs/${encodeURIComponent(id)}/${action}`;const options={method};if(action==='retry')options.headers=credentialHeaders();try{const r=await fetch(endpoint,options);const data=await r.json();if(!r.ok)throw Error(data.error||data.detail||`${action} failed`);if(action==='delete'){state.lastDeleted=id;$('restoreLastButton').disabled=false;if(state.activeJobId===id)newProject();}toast(action==='delete'?'Project moved to trash.':action==='duplicate'?'Draft duplicated.':action==='retry'?'Project queued again.':'Project updated.');if(action==='retry'){state.activeJobId=id;openJob(id);}loadJobs();}catch(e){toast(e.message,true);}finally{if(button)button.disabled=false;}}
    async function restoreLastDeleted(){if(!state.lastDeleted)return;const id=state.lastDeleted;const b=$('restoreLastButton');b.disabled=true;try{const r=await fetch(`/api/jobs/${encodeURIComponent(id)}/restore`,{method:'POST'});const d=await r.json();if(!r.ok)throw Error(d.detail||'Restore failed');state.lastDeleted=null;toast('Project restored.');loadJobs();}catch(e){toast(e.message,true);b.disabled=false;}}
    function renderQueue(){
      const list=state.jobs.slice(0,12);
      $('queueList').innerHTML=list.length?list.map(j=>{const pct=StudioUI.progressPercent(j);return `<div class="queue-item" data-open-job="${esc(j.id)}" tabindex="0" role="button" aria-label="Open queued project ${esc(j.name||j.request?.url||j.id)}"><div class="queue-copy"><strong>${esc(j.name||j.request?.url||j.id)}</strong><small>${esc(j.status)} - ${esc(j.stage||'')}</small></div><div class="mini-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}" aria-label="Progress"><span style="width:${pct}%"></span></div></div>`;}).join(''):'<div class="empty" style="padding:18px">No queued projects.</div>';
      document.querySelectorAll('.queue-item[data-open-job]').forEach(el=>{el.addEventListener('click',()=>openJob(el.dataset.openJob));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openJob(el.dataset.openJob);}});});
    }
    function renderBatchMonitor(){
      const panel=$('batchPanel'); const list=$('batchList'); const summary=$('batchSummary');
      if(!panel||!list)return;
      if(!state.batchJobs.length){panel.hidden=true;return;}
      panel.hidden=false;
      const done=state.batchJobs.filter(job=>['done','error','cancelled','interrupted'].includes(String(job.status||'').toLowerCase())).length;
      const active=state.batchJobs.filter(job=>['queued','running'].includes(String(job.status||'').toLowerCase())).length;
      if(summary)summary.textContent=`${done} of ${state.batchJobs.length} complete${active?` - ${active} still running`:''}`;
      list.innerHTML=state.batchJobs.map(job=>{const pct=StudioUI.progressPercent(job);const status=String(job.status||'queued');const title=job.name||job.request?.url||job.id;const canCancel=['queued','running'].includes(status);return `<div class="batch-row"><button class="ghost batch-open" type="button" data-batch-open="${esc(job.id)}">${esc(title)}</button><div class="batch-progress"><div class="progress-head"><span>${esc(job.message||job.stage||status)}</span><strong>${Math.round(pct)}%</strong></div><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}" aria-label="${esc(title)} progress"><span style="width:${pct}%"></span></div></div><span class="badge ${statusClass(status)}">${esc(status)}</span>${canCancel?`<button class="ghost" type="button" data-batch-cancel="${esc(job.id)}">Cancel</button>`:''}</div>`;}).join('');
      list.querySelectorAll('[data-batch-open]').forEach(button=>button.addEventListener('click',()=>openJob(button.dataset.batchOpen)));
      list.querySelectorAll('[data-batch-cancel]').forEach(button=>button.addEventListener('click',()=>cancelJob(button.dataset.batchCancel,button)));
      const cancel=$('cancelBatchButton'); if(cancel)cancel.disabled=active===0;
    }
    let librarySearchTimer=null; $('librarySearch').addEventListener('input',e=>{if(librarySearchTimer)clearTimeout(librarySearchTimer);const query=e.target.value.trim();librarySearchTimer=setTimeout(()=>loadJobs(query),180);});
    $('showArchived').addEventListener('change',e=>{state.showArchived=e.target.checked;loadJobs();});
    async function startJob(){
      if(state.uploading)return;
      const req=readRequest();
      if(!req.url&&!$('batchUrls').value.trim()){toast('Add a YouTube URL, local path, or video file first.',true);return;}
      const headers={'Content-Type':'application/json',...credentialHeaders()};
      if(req.mode==='api'&&!headers['X-MuAPI-Key']&&!state.setup?.keys?.muapi_configured){toast('API mode needs a MuAPI key. Open Settings to enter it.',true);setView('settings');return;}
      const urls=$('batchUrls').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
      if(req.url)urls.unshift(req.url);
      const payload=urls.length>1?{...req,urls,url:undefined}:req;
      delete payload.url;
      if(urls.length===1)payload.url=urls[0];
      setBusy(true);
      try{
        const endpoint=urls.length>1?'/api/jobs/batch':'/api/jobs';
        const data=await StudioAPI.json(endpoint,{method:'POST',headers,body:JSON.stringify(payload)});
        const jobs=Array.isArray(data.jobs)?data.jobs.filter(job=>job&&job.id):[data];
        state.batchJobs=jobs.length>1?jobs:[];
        state.batchActive=jobs.length>1;
        state.batchMonitors={};
        renderBatchMonitor();
        const job=jobs[0];
        if(!job?.id)throw Error('The server did not return a job id');
        state.activeJobId=job.id;state.activeJob=job;
        $('jobIdBadge').hidden=false;$('jobIdBadge').textContent=job.id;
        setStatus(job);
        if(jobs.length>1)watchBatchJobs(jobs);else watch(job.id);
        toast(jobs.length>1?`${jobs.length} projects added to the queue.`:'Project added to the queue.');
      }catch(e){toast(e.message,true);}finally{setBusy(false);}
    }
    async function cancelJob(id,button=null){
      if(!id)return;
      if(button)button.disabled=true;
      try{
        const data=await StudioAPI.json(`/api/jobs/${encodeURIComponent(id)}/cancel`,{method:'POST'});
        const index=state.batchJobs.findIndex(job=>job.id===id);
        if(index>=0){state.batchJobs[index]=data;renderBatchMonitor();}
        if(state.activeJobId===id)setStatus(data);
        toast(data.status==='cancelled'?'Job cancelled.':'Job is no longer running.');
      }catch(e){toast(e.message,true);}finally{if(button)button.disabled=false;}
    }
    async function cancelActiveJob(){const id=state.activeJobId;if(!id)return;await cancelJob(id,$('cancelButton'));}
    async function cancelBatch(){
      const active=state.batchJobs.filter(job=>['queued','running'].includes(String(job.status||'')));
      if(!active.length)return;
      const button=$('cancelBatchButton');if(button)button.disabled=true;
      await Promise.all(active.map(job=>cancelJob(job.id)));
      renderBatchMonitor();
    }
    function watchBatchJobs(jobs){
      Object.values(state.batchMonitors).forEach(monitor=>monitor?.stop?.());
      state.batchMonitors={};
      jobs.forEach(job=>{
        state.batchMonitors[job.id]=StudioAPI.watchJob(job.id,{
          onUpdate:next=>{
            const index=state.batchJobs.findIndex(item=>item.id===job.id);
            if(index>=0)state.batchJobs[index]=next;
            if(state.activeJobId===job.id)setStatus(next);
            renderBatchMonitor();
          },
          onEnd:()=>{if(state.batchJobs.every(item=>['done','error','cancelled','interrupted'].includes(String(item.status||'')))){state.batchActive=false;loadJobs();}},
          onRetry:(count)=>{if(count===1)StudioUI.announce('Live updates paused; polling for job progress.');},
          onError:error=>toast(error.message||'Could not reconnect to one of the batch jobs.',true)
        });
      });
    }
    function setBusy(busy){$('generateButton').disabled=busy;$('generateButton').textContent=busy?'Queued...':'Generate shorts';if($('jobProgress'))$('jobProgress').hidden=!busy&&!['queued','running'].includes(String(state.activeJob?.status||''));}
    function statusClass(status){return status==='done'?'done':status==='error'?'error':status==='running'?'run':status==='interrupted'?'run':status==='cancelled'?'error':'';}
    function setStatus(job){
      if(!job)return;
      state.activeJob=job;
      const status=String(job.status||'queued');
      const cancel=$('cancelButton');
      if(cancel){cancel.hidden=!['queued','running'].includes(status);cancel.disabled=false;}
      $('jobBadge').textContent=status==='done'?'Completed':status==='running'?'Rendering':status==='error'?'Needs attention':status==='interrupted'?'Resume available':status==='cancelled'?'Cancelled':status==='draft'?'Draft':'Queued';
      $('jobBadge').className=`badge ${statusClass(status)}`;
      const pct=Number.isFinite(Number(job.progress))?` ${Math.round(Number(job.progress))}%`:'';
      const eta=Number(job.eta_seconds)>0?` - about ${Math.ceil(Number(job.eta_seconds))}s left`:'';
      $('sourceBadge').textContent=(job.message||job.stage||'Ready')+pct;
      $('renderNote').innerHTML=`<b>${esc(job.stage||'ready')}.</b> ${esc(job.message||'Waiting for work.')} <span class="eyebrow">${esc(pct)}${esc(eta)}</span>`;
      if($('jobProgress')){$('jobProgress').hidden=!['queued','running'].includes(status)&&status!=='done';StudioUI.renderProgress($('jobProgress'),job);}
      $('logsButton').href=`/api/jobs/${encodeURIComponent(job.id)}/logs`;$('logsButton').style.pointerEvents='auto';$('logsButton').style.opacity='1';$('openOutputButton').disabled=!job.output_dir;
      if(status==='done'&&job.result){state.result=job.result;renderResult(job.result,job.id);renderTimeline(job.id);document.querySelectorAll('.editor-tools-panel').forEach(panel=>panel.hidden=$('mode')?.value==='api');}
      else if(status!=='running'&&status!=='queued'){state.result=null;$('clipGrid').innerHTML='<div class="empty">Rendered clips will appear here.</div>';resetPreview();}
      syncHistoryButtons();
      if(status==='error')toast(job.error||job.message||'Job failed',true);
      StudioUI.announce(`${job.stage||status}: ${job.message||''}`);
    }
    function watch(id){stopPoll();state.activeJobId=id;const monitor=StudioAPI.watchJob(id,{onUpdate:setStatus,onEnd:()=>loadJobs(),onRetry:(count)=>{if(count===1)StudioUI.announce('Live updates paused; polling for job progress.');},onError:error=>toast(error.message||'Could not reconnect to Shorts Studio. Use Refresh to try again.',true)});state.jobMonitor=monitor;}
    function stopPoll(){state.jobMonitor?.stop?.();state.jobMonitor=null;Object.values(state.batchMonitors||{}).forEach(monitor=>monitor?.stop?.());state.batchMonitors={};if(state.poll)clearInterval(state.poll);state.poll=null;if(state.eventSource){state.eventSource.close();state.eventSource=null;}state.pollFailures=0;}
    async function pollOnce(id){try{setStatus(await StudioAPI.json(`/api/jobs/${encodeURIComponent(id)}`));}catch(error){toast(error.message||'Could not load job',true);}}
    async function openJob(id){setView('workspace');try{const r=await fetch(`/api/jobs/${encodeURIComponent(id)}`);const job=await r.json();if(!r.ok)throw Error(job.error||job.detail||'Could not open project');state.activeJobId=id;state.activeJob=job;$('projectName').value=job.name||job.request?.url||'Untitled project';applyRequest(job.request||{});$('jobIdBadge').hidden=false;$('jobIdBadge').textContent=id;setStatus(job);if(job.status==='running')watch(id);if(job.status==='done')renderTimeline(id);}catch(e){toast(e.message,true);}}
